begin;
do $$declare own uuid;student uuid;os uuid;ss uuid;dm uuid;notice bigint;msg bigint;nonce uuid:=gen_random_uuid();n integer;ann uuid;graded uuid;begin
 select owner_id into own from acc_private.owner_setup where id;select id into student from public.acc_profiles where id<>own and role='student' and not suspended limit 1;
 select id into os from auth.sessions where user_id=own limit 1;select id into ss from auth.sessions where user_id=student limit 1;
 if own is null or student is null or os is null or ss is null then raise exception 'Two existing real accounts/sessions required';end if;
 perform set_config('nt.own',own::text,true);perform set_config('nt.student',student::text,true);perform set_config('nt.os',os::text,true);perform set_config('nt.ss',ss::text,true);
 delete from public.acc_notifications where person in(own,student);delete from public.acc_inbox_settings where person in(own,student);delete from public.acc_inbox_rooms where person in(own,student);
 delete from public.acc_preferences where (person=own and target=student)or(person=student and target=own);
 delete from public.acc_friends where (sender=own and recipient=student)or(sender=student and recipient=own);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',own,'session_id',os,'role','authenticated')::text,true);
 perform public.acc_call('friend',jsonb_build_object('target',student));perform public.acc_call('friend',jsonb_build_object('target',student));
 if (select count(*) from public.acc_notifications where person=student and kind='friend_request')<>1 then raise exception 'Friend notification duplicated or missing';end if;
 select id into notice from public.acc_notifications where person=student and kind='friend_request';perform public.acc_call('noticeRead',jsonb_build_object('id',notice));
 if (select read_at from public.acc_notifications where id=notice) is not null then raise exception 'Other account marked notification read';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',student,'session_id',ss,'role','authenticated')::text,true);
 if jsonb_array_length(public.acc_call('inboxSnapshot')->'notices')<>1 then raise exception 'Incoming request absent';end if;
 perform public.acc_call('noticeRead',jsonb_build_object('id',notice));if (select read_at from public.acc_notifications where id=notice) is null then raise exception 'Read did not persist';end if;
 perform public.acc_call('friend',jsonb_build_object('target',own,'choice','accept'));perform public.acc_call('friend',jsonb_build_object('target',own,'choice','accept'));
 if (select count(*) from public.acc_notifications where person=own and kind='friend_accepted')<>1 then raise exception 'Acceptance notification missing/duplicated';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',own,'session_id',os,'role','authenticated')::text,true);
 dm:=(public.acc_call('dm',jsonb_build_object('target',student))->>'room')::uuid;perform set_config('nt.dm',dm::text,true);
 update public.acc_profiles set last_post=null where id=own;
 perform public.acc_call('send',jsonb_build_object('room',dm,'body','Rollback-only notification privacy test','nonce',nonce));perform public.acc_call('send',jsonb_build_object('room',dm,'body','Rollback-only notification privacy test','nonce',nonce));
 if (select count(*) from public.acc_notifications where person=student and kind='dm')<>1 then raise exception 'DM notification missing/duplicated';end if;
 select id,message into notice,msg from public.acc_notifications where person=student and kind='dm';perform set_config('nt.notice',notice::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',student,'session_id',ss,'role','authenticated')::text,true);
 if not exists(select 1 from jsonb_array_elements(public.acc_call('inboxSnapshot')->'dms')x where x->>'id'=dm::text and (x->>'unread')::integer>=1) then raise exception 'DM library unread missing';end if;
 perform public.acc_call('inboxRoom',jsonb_build_object('room',dm,'pinned',true,'muted',true));
 if exists(select 1 from jsonb_array_elements(public.acc_call('inboxSnapshot')->'notices')x where x->>'kind'='dm') then raise exception 'Muted room notification visible';end if;
 if not exists(select 1 from jsonb_array_elements(public.acc_call('inboxSnapshot')->'dms')x where x->>'id'=dm::text and (x->>'pinned')::boolean and (x->>'unread')::integer=0) then raise exception 'Pin/mute persistence failed';end if;
 perform public.acc_call('inboxRoom',jsonb_build_object('room',dm,'pinned',true,'muted',false));
 perform public.acc_call('preference',jsonb_build_object('target',own,'blocked',true));
 if exists(select 1 from jsonb_array_elements(public.acc_call('inboxSnapshot')->'notices')x where x->>'actor'=own::text) then raise exception 'Blocked notification exposed';end if;
 perform public.acc_call('preference',jsonb_build_object('target',own,'blocked',false,'muted',false));
 perform public.acc_call('read',jsonb_build_object('room',dm));if (select read_at from public.acc_notifications where id=notice) is null then raise exception 'Conversation read did not sync notices';end if;
 perform public.acc_call('inboxSettings','{"dms":false,"friends":false,"announcements":false,"sound":false}');
 if (public.acc_call('inboxSnapshot')->'settings'->>'dms')::boolean then raise exception 'Notification settings not persistent';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',own,'session_id',os,'role','authenticated')::text,true);
 select count(*) into n from public.acc_notifications where person=student;update public.acc_profiles set last_post=null where id=own;
 perform public.acc_call('send',jsonb_build_object('room',dm,'body','Muted notification test','nonce',gen_random_uuid()));
 if (select count(*) from public.acc_notifications where person=student)<>n then raise exception 'Muted category created notification';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',student,'session_id',ss,'role','authenticated')::text,true);
 perform public.acc_call('inboxSettings','{"dms":true,"friends":true,"announcements":true,"sound":false}');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',own,'session_id',os,'role','authenticated')::text,true);
 select id into ann from public.acc_rooms where name='announcements' and kind='school' limit 1;update public.acc_profiles set last_post=null where id=own;
 perform public.acc_call('send',jsonb_build_object('room',ann,'body','Rollback owner announcement','nonce',gen_random_uuid()));
 if (select count(*) from public.acc_notifications where person=student and kind='announcement')<>1 then raise exception 'Announcement delivery missing';end if;
 -- Even explicitly granted announcement permission cannot bypass new owner-only policy.
 insert into acc_private.moderators(person,permissions) values(student,'{"announcements":true}') on conflict(person) do update set permissions=excluded.permissions;update public.acc_profiles set role='moderator' where id=student;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',student,'session_id',ss,'role','authenticated')::text,true);
 begin perform public.acc_call('send',jsonb_build_object('room',ann,'body','Forbidden moderator announcement','nonce',gen_random_uuid()));raise exception 'Moderator posted announcement';exception when others then if sqlerrm='Moderator posted announcement' then raise;end if;end;
 update public.acc_profiles set role='student' where id=student;delete from acc_private.moderators where person=student;
 perform public.acc_call('noticesReadAll',jsonb_build_object('through',(select max(id) from public.acc_notifications where person=student)));
 if (public.acc_call('inboxSnapshot')->>'unread')::integer<>0 then raise exception 'Mark all read failed';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',own,'session_id',os,'role','authenticated')::text,true);
 graded:=(public.acc_call('channelSave',jsonb_build_object('name','Rollback grade announcement','grade',9,'announcement',true))->>'room')::uuid;
 select id into graded from public.acc_rooms where name='Rollback grade announcement' limit 1;update acc_private.grades set grade=12 where person=student;update public.acc_profiles set last_post=null where id=own;
 select count(*) into n from public.acc_notifications where person=student;
 perform public.acc_call('send',jsonb_build_object('room',graded,'body','Restricted grade announcement','nonce',gen_random_uuid()));
 if (select count(*) from public.acc_notifications where person=student)<>n then raise exception 'Cross-grade announcement notified';end if;
 perform public.acc_call('deleteMessage',jsonb_build_object('message',msg));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',student,'session_id',ss,'role','authenticated')::text,true);
 if exists(select 1 from jsonb_array_elements(public.acc_call('inboxSnapshot')->'notices')x where x->>'message'=msg::text) then raise exception 'Deleted message notification exposed';end if;
end $$;
set local role authenticated;
do $$begin
 if exists(select 1 from public.acc_notifications where person<>auth.uid()) or exists(select 1 from public.acc_inbox_settings where person<>auth.uid()) or exists(select 1 from public.acc_inbox_rooms where person<>auth.uid()) then raise exception 'Cross-account RLS leak';end if;
 if has_table_privilege(current_user,'public.acc_notifications','INSERT') or has_table_privilege(current_user,'public.acc_notifications','UPDATE') or has_function_privilege(current_user,'acc_private.emit_notice(uuid,uuid,text,uuid,bigint,text)','EXECUTE') then raise exception 'Client can forge notifications';end if;
 if has_function_privilege(current_user,'acc_private.manage(text,jsonb)','EXECUTE') then raise exception 'Old announcement bypass remains';end if;
end $$;
reset role;
do $$declare own uuid:=current_setting('nt.own')::uuid;student uuid:=current_setting('nt.student')::uuid;begin
 perform set_config('request.jwt.claims',jsonb_build_object('sub',own,'session_id',current_setting('nt.os'),'role','authenticated')::text,true);
 perform public.acc_call('suspend',jsonb_build_object('target',student,'enabled',true));
 perform set_config('request.jwt.claims',jsonb_build_object('sub',student,'session_id',current_setting('nt.ss'),'role','authenticated')::text,true);
 begin perform public.acc_call('inboxSnapshot');raise exception 'Suspended account read inbox';exception when others then if sqlerrm='Suspended account read inbox' then raise;end if;end;
end $$;
set local role authenticated;
do $$begin if exists(select 1 from public.acc_notifications) or exists(select 1 from public.acc_inbox_settings) or exists(select 1 from public.acc_inbox_rooms) then raise exception 'Suspended account RLS leak';end if;end $$;
reset role;
set local role anon;
do $$begin if has_table_privilege(current_user,'public.acc_notifications','SELECT') then raise exception 'Anonymous notifications exposed';end if;end $$;
reset role;
rollback;
select 'PASS two existing real account contexts: friend request/accept deduplication, DM retries, read persistence, room pins/mutes, blocks, settings, announcement owner-only/grade rules, deleted-message suppression, RLS and forgery denial. All test data rolled back; no real browser WebSocket claim.' result;
